class Inputs(HTMLParser):
 def __init__(self):super().__init__();self.inputs=[];self.selects=0
 def handle_starttag(self,tag,attrs):
  if tag=='input':self.inputs.append(dict(attrs).get('id'))
  if tag=='select':self.selects+=1

